import PDFDocument from 'pdfkit';
import QRCode from 'qrcode';
import { files } from '../integrations/storage';
import { formatDate } from '../lib/dates';
import { formatKobo } from '../lib/money';
import { brandTokens, parseHex, toHex } from '../calc/contrast';

/**
 * PDFs are generated by the worker with pdfkit (the documented fallback to headless Chromium, so the API runs on any host).
 * Receipts, report cards and broadsheets carry the school's logo and colours. Money prints as NGN because the built-in
 * fonts have no naira sign.
 */

export interface Brand {
  name: string;
  motto?: string;
  logoRef?: string;
  stampRef?: string;
  signatureRef?: string;
  primary: string;
  secondary: string;
  address?: string;
  phone?: string;
  email?: string;
}

export const NGN = (kobo: number) => `NGN ${formatKobo(kobo)}`;

export function newDoc(opts: { size?: 'A4'; landscape?: boolean; margin?: number; info?: Record<string, string> } = {}) {
  const doc = new PDFDocument({ size: opts.size ?? 'A4', layout: opts.landscape ? 'landscape' : 'portrait', margin: opts.margin ?? 40, info: { Producer: 'Viriah', ...opts.info } });
  const chunks: Buffer[] = [];
  doc.on('data', (c: Buffer) => chunks.push(c));
  const done = new Promise<Buffer>((resolve, reject) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
  });
  return { doc, done };
}

/** Logo, stamp and signature images. WebP is not supported by pdfkit, so those are skipped rather than failing the document. */
export async function loadImage(ref?: string): Promise<Buffer | undefined> {
  if (!ref || !/\.(png|jpe?g)$/i.test(ref)) return undefined;
  try {
    return await files.getBuffer(ref);
  } catch {
    return undefined;
  }
}

export const qrPng = (text: string) => QRCode.toBuffer(text, { margin: 1, width: 180, errorCorrectionLevel: 'M' });

export function header(doc: PDFKit.PDFDocument, brand: Brand, logo: Buffer | undefined, title: string, subtitle?: string) {
  const tokens = brandTokens(brand.primary, brand.secondary);
  const left = doc.page.margins.left;
  const width = doc.page.width - doc.page.margins.left - doc.page.margins.right;
  const top = doc.y;
  doc.rect(left, top, width, 6).fill(tokens.primary);
  let x = left;
  const y = top + 16;
  if (logo) {
    try {
      doc.image(logo, left, y, { fit: [56, 56] });
      x = left + 68;
    } catch {
      /* unreadable image: carry on without it */
    }
  }
  doc.fillColor('#111111').font('Helvetica-Bold').fontSize(16).text(brand.name, x, y, { width: width - (x - left) - 130 });
  if (brand.motto) doc.font('Helvetica-Oblique').fontSize(9).fillColor('#444444').text(brand.motto, x, doc.y);
  doc.font('Helvetica').fontSize(8).fillColor('#555555');
  const contact = [brand.address, brand.phone, brand.email].filter(Boolean).join('  |  ');
  if (contact) doc.text(contact, x, doc.y + 2, { width: width - (x - left) - 130 });
  doc.font('Helvetica-Bold').fontSize(14).fillColor(tokens.primaryText).text(title, left + width - 130, y, { width: 130, align: 'right' });
  if (subtitle) doc.font('Helvetica').fontSize(9).fillColor('#444444').text(subtitle, left + width - 130, doc.y, { width: 130, align: 'right' });
  doc.y = Math.max(doc.y, y + 62) + 8;
  doc.moveTo(left, doc.y).lineTo(left + width, doc.y).lineWidth(0.5).strokeColor('#bbbbbb').stroke();
  doc.y += 10;
  doc.fillColor('#111111');
  return tokens;
}

export function table(doc: PDFKit.PDFDocument, columns: Array<{ header: string; width: number; align?: 'left' | 'right' | 'center' }>, rows: string[][], opts: { headFill?: string; headColor?: string; fontSize?: number; rowHeight?: number } = {}) {
  const left = doc.page.margins.left;
  const fs = opts.fontSize ?? 9;
  const rh = opts.rowHeight ?? fs + 8;
  const totalW = columns.reduce((a, c) => a + c.width, 0);
  const drawHead = () => {
    const y = doc.y;
    doc.rect(left, y, totalW, rh).fill(opts.headFill ?? '#eeeeee');
    let x = left;
    doc.fillColor(opts.headColor ?? '#111111').font('Helvetica-Bold').fontSize(fs);
    for (const c of columns) {
      doc.text(c.header, x + 4, y + 4, { width: c.width - 8, align: c.align ?? 'left', lineBreak: false });
      x += c.width;
    }
    doc.y = y + rh;
  };
  drawHead();
  doc.font('Helvetica').fontSize(fs).fillColor('#111111');
  rows.forEach((row, i) => {
    if (doc.y + rh > doc.page.height - doc.page.margins.bottom) {
      doc.addPage();
      drawHead();
      doc.font('Helvetica').fontSize(fs).fillColor('#111111');
    }
    const y = doc.y;
    if (i % 2 === 1) doc.rect(left, y, totalW, rh).fill('#f7f7f7').fillColor('#111111');
    let x = left;
    columns.forEach((c, ci) => {
      doc.text(row[ci] ?? '', x + 4, y + 4, { width: c.width - 8, align: c.align ?? 'left', lineBreak: false, ellipsis: true });
      x += c.width;
    });
    doc.y = y + rh;
  });
  doc.x = left;
}

export function watermark(doc: PDFKit.PDFDocument, text: string, colour = '#cc0000') {
  doc.save();
  doc.rotate(-30, { origin: [doc.page.width / 2, doc.page.height / 2] });
  doc.fillColor(colour).opacity(0.14).font('Helvetica-Bold').fontSize(90).text(text, 0, doc.page.height / 2 - 50, { width: doc.page.width, align: 'center' });
  doc.opacity(1).restore();
}

// ------------------------------------------------------------------ receipt

export interface ReceiptData {
  number: string;
  date: string; // YYYY-MM-DD
  verificationCode: string;
  verifyUrl: string;
  void: boolean;
  student?: { name: string; admissionNumber?: string; className?: string };
  payerName?: string;
  method: string;
  lines: Array<{ invoiceNumber: string; label: string; amountKobo: number }>;
  amountKobo: number;
  balanceAfterKobo: number;
  reference?: string;
  revised?: boolean;
}

export async function receiptPdf(brand: Brand, data: ReceiptData): Promise<Buffer> {
  const { doc, done } = newDoc({ info: { Title: `Receipt ${data.number}` } });
  const logo = await loadImage(brand.logoRef);
  const tokens = header(doc, brand, logo, 'RECEIPT', data.number);
  const left = doc.page.margins.left;
  const width = doc.page.width - left - doc.page.margins.right;

  const kv = (k: string, v: string, y: number, x = left) => {
    doc.font('Helvetica').fontSize(8).fillColor('#666666').text(k.toUpperCase(), x, y, { width: 200 });
    doc.font('Helvetica-Bold').fontSize(10).fillColor('#111111').text(v || '-', x, doc.y, { width: 240 });
  };
  const y0 = doc.y;
  kv('Date', formatDate(data.date), y0);
  kv('Payment method', data.method, y0, left + 270);
  const y1 = doc.y + 8;
  kv('Received from', data.payerName ?? '-', y1);
  kv('For student', data.student ? `${data.student.name}${data.student.admissionNumber ? ` (${data.student.admissionNumber})` : ''}${data.student.className ? `, ${data.student.className}` : ''}` : '-', y1, left + 270);
  doc.y = doc.y + 14;

  table(
    doc,
    [
      { header: 'Invoice', width: 110 },
      { header: 'Description', width: width - 110 - 130 },
      { header: 'Amount', width: 130, align: 'right' }
    ],
    data.lines.map((l) => [l.invoiceNumber, l.label, NGN(l.amountKobo)]),
    { headFill: tokens.primary, headColor: tokens.primaryContrast }
  );
  doc.y += 10;
  doc.font('Helvetica-Bold').fontSize(13).fillColor('#111111').text(`Amount paid: ${NGN(data.amountKobo)}`, left, doc.y, { width, align: 'right' });
  doc.font('Helvetica').fontSize(10).fillColor('#444444').text(`Balance left: ${NGN(data.balanceAfterKobo)}`, left, doc.y + 2, { width, align: 'right' });

  // Verification
  const qy = Math.max(doc.y + 24, 520);
  const qr = await qrPng(data.verifyUrl);
  doc.image(qr, left, qy, { width: 90 });
  doc.font('Helvetica-Bold').fontSize(9).fillColor('#111111').text('Verify this receipt', left + 104, qy + 6);
  doc.font('Helvetica').fontSize(8).fillColor('#555555').text(`Scan the code, or enter ${data.verificationCode} on the school website.\n${data.verifyUrl}`, left + 104, doc.y + 2, { width: 300 });
  if (data.reference) doc.text(`Reference: ${data.reference}`, left + 104, doc.y + 4);
  if (data.revised) doc.text('Revised copy.', left + 104, doc.y + 2);

  if (data.void) watermark(doc, 'VOID');
  doc.end();
  return done;
}

export const hexOr = (hex: string, fallback = '#1d4ed8') => toHex(parseHex(hex) ?? parseHex(fallback)!);
